-- Q03 · Conta do proprietário DEPOIS de instalar = registo P05, ainda exatamente 1 conta, sem perfil.
-- Substituir __EMAIL_AUTORIZADO__ como em P04/P05 e os marcadores __P05_B01/B02/B03__ pelas impressões do P05.
-- A comparação é feita pela própria consulta: qualquer diferença => REPROVADO. Não corrigir à mão.
-- Lê auth.identities: sem permissão => ERRO => BLOQUEIO (B11).
-- Só leitura: um único SELECT. Resultado: uma linha por verificação. Se alguma
-- verificação falhar (ou der NULL), a consulta TERMINA EM ERRO com "REPROVADO: <id> obtido=<valor> | …".
WITH alvo AS (SELECT lower('__EMAIL_AUTORIZADO__') AS email),
u AS (SELECT au.id, lower(au.email) AS email, to_jsonb(au) AS j FROM auth.users au, alvo WHERE lower(au.email) = alvo.email),
r AS (SELECT ur.id, ur.user_id, ur.role, ur.created_at FROM public.user_roles ur WHERE ur.user_id IN (SELECT id FROM u)),
c(id, verificacao, ok, esperado, obtido) AS (
  SELECT 'Q03-00'::text, 'marcadores substituídos (email e 3 impressões sha256 do P05)'::text, ((SELECT email FROM alvo) ~ '^[^_][^@]*@[^@]+\.[^@]+$' AND '__P05_B01_CONTA__' ~ '^[0-9a-f]{64}$' AND '__P05_B02_IDENTIDADES__' ~ '^[0-9a-f]{64}$' AND '__P05_B03_PAPEIS__' ~ '^[0-9a-f]{64}$')::boolean, 'todos'::text, ('ver cabeçalho do ficheiro')::text
  UNION ALL SELECT 'Q03-01'::text, 'o staging continua com EXATAMENTE 1 conta'::text, ((SELECT count(*) FROM auth.users) = 1)::boolean, '1'::text, ((SELECT count(*) FROM auth.users)::text)::text
  UNION ALL SELECT 'Q03-02'::text, 'essa conta é a do email autorizado'::text, ((SELECT count(*) FROM u) = 1)::boolean, '1'::text, ((SELECT count(*) FROM u)::text)::text
  UNION ALL SELECT 'Q03-03'::text, 'conta (campos estáveis) igual ao P05-B01'::text, (encode(sha256(convert_to((SELECT string_agg(coalesce(u.j ->> 'id', '~') || '|' || coalesce(u.j ->> 'email', '~') || '|' || coalesce(u.j ->> 'phone', '~') || '|' || coalesce(u.j ->> 'aud', '~') || '|' || coalesce(u.j ->> 'role', '~') || '|' || coalesce(u.j ->> 'is_sso_user', '~') || '|' || coalesce(u.j ->> 'is_anonymous', '~') || '|' || coalesce(u.j ->> 'raw_app_meta_data', '~') || '|' || coalesce(extract(epoch FROM (u.j ->> 'email_confirmed_at')::timestamptz)::text, '~') || '|' || coalesce(extract(epoch FROM (u.j ->> 'phone_confirmed_at')::timestamptz)::text, '~') || '|' || coalesce(extract(epoch FROM (u.j ->> 'created_at')::timestamptz)::text, '~') || '|' || coalesce(extract(epoch FROM (u.j ->> 'banned_until')::timestamptz)::text, '~') || '|' || coalesce(extract(epoch FROM (u.j ->> 'deleted_at')::timestamptz)::text, '~'), E'\n' ORDER BY u.id) FROM u), 'UTF8')), 'hex') = '__P05_B01_CONTA__')::boolean, '= P05-B01'::text, (encode(sha256(convert_to((SELECT string_agg(coalesce(u.j ->> 'id', '~') || '|' || coalesce(u.j ->> 'email', '~') || '|' || coalesce(u.j ->> 'phone', '~') || '|' || coalesce(u.j ->> 'aud', '~') || '|' || coalesce(u.j ->> 'role', '~') || '|' || coalesce(u.j ->> 'is_sso_user', '~') || '|' || coalesce(u.j ->> 'is_anonymous', '~') || '|' || coalesce(u.j ->> 'raw_app_meta_data', '~') || '|' || coalesce(extract(epoch FROM (u.j ->> 'email_confirmed_at')::timestamptz)::text, '~') || '|' || coalesce(extract(epoch FROM (u.j ->> 'phone_confirmed_at')::timestamptz)::text, '~') || '|' || coalesce(extract(epoch FROM (u.j ->> 'created_at')::timestamptz)::text, '~') || '|' || coalesce(extract(epoch FROM (u.j ->> 'banned_until')::timestamptz)::text, '~') || '|' || coalesce(extract(epoch FROM (u.j ->> 'deleted_at')::timestamptz)::text, '~'), E'\n' ORDER BY u.id) FROM u), 'UTF8')), 'hex'))::text
  UNION ALL SELECT 'Q03-04'::text, 'estado da conta: confirmada, não bloqueada, não apagada, não anónima'::text, ((SELECT bool_and(j ->> 'email_confirmed_at' IS NOT NULL AND (j ->> 'banned_until' IS NULL OR (j ->> 'banned_until')::timestamptz < now()) AND j ->> 'deleted_at' IS NULL AND coalesce(j ->> 'is_anonymous', 'false') = 'false') FROM u))::boolean, 'sim'::text, ((SELECT 'confirmada=' || (j ->> 'email_confirmed_at' IS NOT NULL)::text || ' bloqueio=' || coalesce(j ->> 'banned_until', '-') || ' apagada=' || coalesce(j ->> 'deleted_at', '-') || ' anónima=' || coalesce(j ->> 'is_anonymous', 'false') FROM u))::text
  UNION ALL SELECT 'Q03-05'::text, 'identidades da conta iguais ao P05-B02 e nenhuma identidade de outra conta'::text, (encode(sha256(convert_to((SELECT string_agg(coalesce(to_jsonb(i) ->> 'id', '~') || '|' || coalesce(to_jsonb(i) ->> 'provider', '~') || '|' || coalesce(to_jsonb(i) ->> 'provider_id', '~') || '|' || coalesce(to_jsonb(i) ->> 'user_id', '~') || '|' || coalesce(extract(epoch FROM (to_jsonb(i) ->> 'created_at')::timestamptz)::text, '~') || '|' || coalesce(i.identity_data ->> 'sub', '~') || '|' || coalesce(lower(i.identity_data ->> 'email'), '~'), E'\n' ORDER BY i.provider, to_jsonb(i) ->> 'id') FROM auth.identities i WHERE i.user_id IN (SELECT id FROM u)), 'UTF8')), 'hex') = '__P05_B02_IDENTIDADES__' AND (SELECT count(*) FROM auth.identities) = (SELECT count(*) FROM auth.identities i WHERE i.user_id IN (SELECT id FROM u)))::boolean, '= P05-B02'::text, (encode(sha256(convert_to((SELECT string_agg(coalesce(to_jsonb(i) ->> 'id', '~') || '|' || coalesce(to_jsonb(i) ->> 'provider', '~') || '|' || coalesce(to_jsonb(i) ->> 'provider_id', '~') || '|' || coalesce(to_jsonb(i) ->> 'user_id', '~') || '|' || coalesce(extract(epoch FROM (to_jsonb(i) ->> 'created_at')::timestamptz)::text, '~') || '|' || coalesce(i.identity_data ->> 'sub', '~') || '|' || coalesce(lower(i.identity_data ->> 'email'), '~'), E'\n' ORDER BY i.provider, to_jsonb(i) ->> 'id') FROM auth.identities i WHERE i.user_id IN (SELECT id FROM u)), 'UTF8')), 'hex') || ' (' || (SELECT count(*) FROM auth.identities i WHERE i.user_id IN (SELECT id FROM u))::text || '/' || (SELECT count(*) FROM auth.identities)::text || ')')::text
  UNION ALL SELECT 'Q03-06'::text, 'papéis da conta = exatamente {admin}'::text, (coalesce((SELECT array_agg(role::text ORDER BY role::text) FROM r), '{}') = ARRAY['admin'])::boolean, 'admin'::text, ((SELECT string_agg(role::text, ',' ORDER BY role::text) FROM r))::text
  UNION ALL SELECT 'Q03-07'::text, 'todas as linhas de user_roles iguais ao P05-B03 (nenhum papel novo, alterado ou apagado)'::text, (encode(sha256(convert_to((SELECT string_agg(ur.id::text || '|' || ur.user_id::text || '|' || ur.role::text || '|' || extract(epoch FROM ur.created_at)::text, E'\n' ORDER BY ur.id) FROM public.user_roles ur), 'UTF8')), 'hex') = '__P05_B03_PAPEIS__' AND (SELECT count(*) FROM public.user_roles) = 1)::boolean, '= P05-B03'::text, (encode(sha256(convert_to((SELECT string_agg(ur.id::text || '|' || ur.user_id::text || '|' || ur.role::text || '|' || extract(epoch FROM ur.created_at)::text, E'\n' ORDER BY ur.id) FROM public.user_roles ur), 'UTF8')), 'hex') || ' (' || (SELECT count(*) FROM public.user_roles)::text || ' linhas)')::text
  UNION ALL SELECT 'Q03-08'::text, 'linha do papel admin sem created_by'::text, ((SELECT bool_and(ur.created_by IS NULL) FROM public.user_roles ur WHERE ur.user_id IN (SELECT id FROM u)))::boolean, 'null'::text, ((SELECT string_agg(coalesce(ur.created_by::text, 'null'), ',') FROM public.user_roles ur WHERE ur.user_id IN (SELECT id FROM u)))::text
  UNION ALL SELECT 'Q03-09'::text, 'nenhum perfil V2 (nem para o proprietário, nem para ninguém)'::text, (NOT EXISTS (SELECT 1 FROM public.profiles))::boolean, '0'::text, ((SELECT count(*) FROM public.profiles)::text)::text
  UNION ALL SELECT 'Q03-10'::text, 'sem estado de acesso nem categorias para a conta'::text, (NOT EXISTS (SELECT 1 FROM public.account_access WHERE user_id IN (SELECT id FROM u)) AND NOT EXISTS (SELECT 1 FROM public.property_categories WHERE user_id IN (SELECT id FROM u)))::boolean, '0/0'::text, ((SELECT count(*) FROM public.account_access WHERE user_id IN (SELECT id FROM u))::text || '/' || (SELECT count(*) FROM public.property_categories WHERE user_id IN (SELECT id FROM u))::text)::text
),
v AS (SELECT count(*) AS n, string_agg(id || ' obtido=' || left(coalesce(obtido, 'NULL'), 160), ' | ' ORDER BY id) FILTER (WHERE ok IS NOT TRUE) AS falhas FROM c)
SELECT c.id, c.verificacao, CASE WHEN c.ok IS TRUE THEN 'OK' ELSE 'FALHA' END AS estado, c.esperado, c.obtido,
       CASE WHEN v.n <> 11 THEN ('VEREDITO INVÁLIDO: ' || v.n::text || ' verificações')::int::text
            WHEN v.falhas IS NULL THEN 'APROVADO'
            ELSE ('REPROVADO: ' || v.falhas)::int::text END AS veredito
  FROM c CROSS JOIN v ORDER BY c.id;
